-- Editorial order: the optional swim-speed preparation belongs before the island swim.
do
 local quests=G.chains[10] and G.chains[10].quests or {}
 local routeZones={[8585]="Фералас",[8577]="Серебряный бор",[8578]="Огненные Недра",[8729]="Азшара",[8745]="Силитус"}
 local bookIndex,loveIndex
 for i,q in ipairs(quests) do
  if q.id==8597 then bookIndex=i elseif q.id==8599 then loveIndex=i end
 end
 if bookIndex and loveIndex and loveIndex>bookIndex then quests[bookIndex],quests[loveIndex]=quests[loveIndex],quests[bookIndex] end
 for _,q in ipairs(quests) do
  if routeZones[q.id] then q.zone=routeZones[q.id] end
  if q.id==8599 then
   q.optional=true
   q.note="Не требуется для продолжения цепочки, но крайне рекомендуется: после доставки письма вернитесь к Мередит и получите ускорение плавания перед заплывом за книгой."
  end
 end
end
